import{_ as a,o as t,c as r,aj as i}from"./chunks/framework.C6uXqnaX.js";const c=JSON.parse('{"title":"Angular Routing","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"guide/routing.md","filePath":"guide/routing.md"}'),n={name:"guide/routing.md"};function o(s,e,l,u,g,d){return t(),r("div",null,e[0]||(e[0]=[i('<h1 id="angular-routing" tabindex="-1">Angular Routing <a class="header-anchor" href="#angular-routing" aria-label="Permalink to &quot;Angular Routing&quot;">​</a></h1><p>Routing helps you change what the user sees in a single-page app.</p><p>Angular Router (<code>@angular/router</code>) is the official library for managing navigation in Angular applications and a core part of the framework. It is included by default in all projects created by Angular CLI.</p><h2 id="why-is-routing-necessary-in-a-spa" tabindex="-1">Why is routing necessary in a SPA? <a class="header-anchor" href="#why-is-routing-necessary-in-a-spa" aria-label="Permalink to &quot;Why is routing necessary in a SPA?&quot;">​</a></h2><p>When you navigate to a URL in your web browser, the browser normally makes a network request to a web server and displays the returned HTML page. When you navigate to a different URL, such as clicking a link, the browser makes another network request and replaces the entire page with a new one.</p><p>A single-page application (SPA) differs in that the browser only makes a request to a web server for the first page, the <code>index.html</code>. After that, a client-side router takes over, controlling which content displays based on the URL. When a user navigates to a different URL, the router updates the page&#39;s content in place without triggering a full-page reload.</p><h2 id="how-angular-manages-routing" tabindex="-1">How Angular manages routing <a class="header-anchor" href="#how-angular-manages-routing" aria-label="Permalink to &quot;How Angular manages routing&quot;">​</a></h2><p>Routing in Angular is comprised of three primary parts:</p><ol><li><strong>Routes</strong> define which component displays when a user visits a specific URL.</li><li><strong>Outlets</strong> are placeholders in your templates that dynamically load and render components based on the active route.</li><li><strong>Links</strong> provide a way for users to navigate between different routes in your application without triggering a full page reload.</li></ol><p>In addition, the Angular Routing library offers additional functionality such as:</p><ul><li>Nested routes</li><li>Programmatic navigation</li><li>Route params, queries and wildcards</li><li>Activated route information with <code>ActivatedRoute</code></li><li>Data fetching with route resources and resolvers</li><li>View transition effects</li><li>Navigation guards</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Learn about how you can <a href="/guide/routing/define-routes">define routes using Angular router</a>.</p>',13)]))}const p=a(n,[["render",o]]);export{c as __pageData,p as default};
